import styled from '@emotion/styled';

export const StyledInvestmentBreakdownWrapper = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '16px',
});

export const StyledPageTitleRightContent = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '16px',
});

export const StyledUsaAlertWrapper = styled.div({
  marginBottom: '16px',
  marginTop: '-16px',
});

export const StyledNoDataYetContent = styled.div({
  width: '100%',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
});

export const BrandsCellNoBorder = styled.div({
  ".ag-center-cols-container .ag-cell[col-id='brands']": {
    borderTop: 'none !important',
    borderBottom: 'none !important',
  },
});
